import{_ as a,o as t,c as n,ag as s}from"./chunks/framework.DlQ8ZhpE.js";const u=JSON.parse('{"title":"Auth, Headers and Request Proxy","description":"","frontmatter":{"title":"Auth, Headers and Request Proxy","order":3},"headers":[],"relativePath":"docs/features/auth-and-headers.md","filePath":"en/docs/features/auth-and-headers.md"}'),r={name:"docs/features/auth-and-headers.md"};function o(i,e,d,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="auth-headers-and-request-proxy" tabindex="-1">Auth, Headers and Request Proxy <a class="header-anchor" href="#auth-headers-and-request-proxy" aria-label="Permalink to &quot;Auth, Headers and Request Proxy&quot;">​</a></h1><h2 id="client-authentication" tabindex="-1">Client Authentication <a class="header-anchor" href="#client-authentication" aria-label="Permalink to &quot;Client Authentication&quot;">​</a></h2><p>The <code>container_registry_single</code>, <code>container_registry_any</code> and <code>any_url</code> modes can enable client authentication, requiring visitors to supply a username and password (HTTP Basic Auth). Users can be defined directly in the config file or in an external user file. The user file is reloaded periodically, so the user list can be updated without restarting Pavonis.</p><p>In the container registry modes, when accessing a private upstream registry that requires authentication, the client can include the upstream credentials alongside its own.</p><p>For details, see <a href="./../config/auth">ClientAuthConfig</a>.</p><h2 id="header-management" tabindex="-1">Header Management <a class="header-anchor" href="#header-management" aria-label="Permalink to &quot;Header Management&quot;">​</a></h2><p>Before forwarding a request to an upstream, Pavonis removes reverse proxy headers such as <code>Via</code> and <code>X-Forwarded-For</code>, and headers injected by Cloudflare, by default. This prevents the upstream from learning about the proxy chain. Request and response headers can also be added, modified or deleted as needed.</p><p>For the default deletion list and how to customise it, see <a href="./../config/request#headermodificationconfig-request-headers">RequestConfig</a> and <a href="./../config/response">ResponseConfig</a>.</p><h2 id="request-proxy" tabindex="-1">Request Proxy <a class="header-anchor" href="#request-proxy" aria-label="Permalink to &quot;Request Proxy&quot;">​</a></h2><p>Upstream requests can go through one or more request proxies, supporting <code>http</code>, <code>https</code>, <code>socks5</code> and <code>socks5h</code>. When a proxy is unreachable, Pavonis switches to the next one, and can fall back to a direct connection when all proxies are unavailable. This suits deployments in network-restricted environments.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>servers:  proxy1 ── blocked, skipped</span></span>
<span class="line"><span>          proxy2 ── unreachable, try next</span></span>
<span class="line"><span>          proxy3 ── ✓ reach upstream via proxy3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>all unavailable ──► direct_fallback enabled ? connect directly : return error</span></span></code></pre></div><p>For configuration, see <a href="./../config/request#requestproxyconfig">RequestConfig</a>.</p>`,12)])])}const f=a(r,[["render",o]]);export{u as __pageData,f as default};
